-- Common Table Expressions
WITH customer_metrics AS (SELECT customer_id,count(*) AS order_count,sum(order_total) AS total_value,avg(order_total) AS avg_value FROM core.orders GROUP BY customer_id) SELECT c.customer_id,c.region,m.order_count,m.total_value,m.avg_value FROM customer_metrics m JOIN core.customers c USING(customer_id) WHERE m.order_count>=3 ORDER BY m.total_value DESC LIMIT 100;
WITH item_metrics AS (SELECT p.product_id,sc.category_id,sum(oi.quantity) AS units_sold FROM core.order_items oi JOIN core.products p USING(product_id) JOIN core.subcategories sc USING(subcategory_id) GROUP BY p.product_id,sc.category_id), returns_metrics AS (SELECT product_id,count(*) AS return_records,sum(refund_amount) AS refunded FROM core.returns GROUP BY product_id) SELECT cat.category_name,sum(im.units_sold) AS units_sold,sum(coalesce(rm.return_records,0)) AS returns,sum(coalesce(rm.refunded,0)) AS refunded FROM item_metrics im JOIN core.categories cat USING(category_id) LEFT JOIN returns_metrics rm USING(product_id) GROUP BY cat.category_name ORDER BY refunded DESC;
WITH ranked AS (SELECT order_id,customer_id,order_date,order_total,row_number() OVER(PARTITION BY customer_id ORDER BY order_date DESC,order_id DESC) AS rn FROM core.orders) SELECT customer_id,order_id,order_date,order_total FROM ranked WHERE rn=1 ORDER BY order_date DESC LIMIT 100;
